using System;
using System.IO;
using System.Linq;
using System.IO.Compression;
using System.Xml.Linq;
using System.Text;

public static class WordExporter {
 static readonly XNamespace W="http://schemas.openxmlformats.org/wordprocessingml/2006/main";
 static XElement P(string text,string style=null,bool keep=false){var props=new XElement(W+"pPr",new XElement(W+"widowControl"));if(style!=null)props.Add(new XElement(W+"pStyle",new XAttribute(W+"val",style)));if(keep)props.Add(new XElement(W+"keepNext"));var run=new XElement(W+"r");bool first=true;foreach(string line in (text??"").Replace("\r","").Split('\n')){if(!first)run.Add(new XElement(W+"br"));first=false;run.Add(new XElement(W+"t",new XAttribute(XNamespace.Xml+"space","preserve"),line));}return new XElement(W+"p",props,run);}
 static void Part(ZipArchive zip,string name,XElement xml){var entry=zip.CreateEntry(name);using(var stream=entry.Open())using(var writer=new StreamWriter(stream,new UTF8Encoding(false)))new XDocument(new XDeclaration("1.0","utf-8","yes"),xml).Save(writer);}
 public static void Save(string path,Entry[] rows,string title){string temp=path+"."+Guid.NewGuid().ToString("N")+".tmp";try{using(var stream=File.Create(temp))using(var zip=new ZipArchive(stream,ZipArchiveMode.Create)){
  XNamespace ct="http://schemas.openxmlformats.org/package/2006/content-types",rel="http://schemas.openxmlformats.org/package/2006/relationships";
  Part(zip,"[Content_Types].xml",new XElement(ct+"Types",new XElement(ct+"Default",new XAttribute("Extension","rels"),new XAttribute("ContentType","application/vnd.openxmlformats-package.relationships+xml")),new XElement(ct+"Default",new XAttribute("Extension","xml"),new XAttribute("ContentType","application/xml")),new XElement(ct+"Override",new XAttribute("PartName","/word/document.xml"),new XAttribute("ContentType","application/vnd.openxmlformats-officedocument.wordprocessingml.document.main+xml")),new XElement(ct+"Override",new XAttribute("PartName","/word/styles.xml"),new XAttribute("ContentType","application/vnd.openxmlformats-officedocument.wordprocessingml.styles+xml"))));
  Part(zip,"_rels/.rels",new XElement(rel+"Relationships",new XElement(rel+"Relationship",new XAttribute("Id","rId1"),new XAttribute("Type","http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument"),new XAttribute("Target","word/document.xml"))));
  Part(zip,"word/_rels/document.xml.rels",new XElement(rel+"Relationships",new XElement(rel+"Relationship",new XAttribute("Id","rId1"),new XAttribute("Type","http://schemas.openxmlformats.org/officeDocument/2006/relationships/styles"),new XAttribute("Target","styles.xml"))));
  Part(zip,"word/styles.xml",new XElement(W+"styles",new XElement(W+"docDefaults",new XElement(W+"rPrDefault",new XElement(W+"rPr",new XElement(W+"rFonts",new XAttribute(W+"ascii","Calibri"),new XAttribute(W+"hAnsi","Calibri"),new XAttribute(W+"eastAsia","Microsoft YaHei")),new XElement(W+"sz",new XAttribute(W+"val",22)))),new XElement(W+"pPrDefault",new XElement(W+"pPr",new XElement(W+"spacing",new XAttribute(W+"after",100),new XAttribute(W+"line",280),new XAttribute(W+"lineRule","auto"))))),new XElement(W+"style",new XAttribute(W+"type","paragraph"),new XAttribute(W+"styleId","Title"),new XElement(W+"name",new XAttribute(W+"val","Title")),new XElement(W+"rPr",new XElement(W+"b"),new XElement(W+"color",new XAttribute(W+"val","000000")),new XElement(W+"sz",new XAttribute(W+"val",40)))),new XElement(W+"style",new XAttribute(W+"type","paragraph"),new XAttribute(W+"styleId","Heading1"),new XElement(W+"name",new XAttribute(W+"val","heading 1")),new XElement(W+"rPr",new XElement(W+"b"),new XElement(W+"sz",new XAttribute(W+"val",30))))));
  var body=new XElement(W+"body",P(title,"Title"),P("oii背词 · 当前筛选词汇，共 "+rows.Length+" 个。包含完整释义、例句及译文，供集中复习。"));int i=0;foreach(var row in rows){body.Add(P((++i)+"  "+row.Word,"Heading1",true));if(!String.IsNullOrEmpty(row.Phonetic))body.Add(P("/"+row.Phonetic+"/"));body.Add(P(FocusedWindow.FormatMeaning(row.Meaning)));body.Add(P("例句："+row.Example));body.Add(P("译文："+row.Translation));body.Add(P("阅读正文 "+row.Count+" 次；听力原文 "+row.OtherCount+" 次。来源："+row.ExampleSource));}body.Add(new XElement(W+"sectPr",new XElement(W+"pgSz",new XAttribute(W+"w",11906),new XAttribute(W+"h",16838)),new XElement(W+"pgMar",new XAttribute(W+"top",1134),new XAttribute(W+"bottom",1134),new XAttribute(W+"left",1134),new XAttribute(W+"right",1134))));Part(zip,"word/document.xml",new XElement(W+"document",body));}
  if(File.Exists(path))File.Replace(temp,path,null);else File.Move(temp,path);
 }finally{if(File.Exists(temp))File.Delete(temp);}}
 public static void Test(){string path=Path.Combine(Path.GetTempPath(),"vocab-export-"+Guid.NewGuid()+".docx");try{Save(path,new[]{new Entry{Word="test & check",Meaning="n. 测试\n检查",Example="A < B & C.",Translation="中文译文",ExampleSource="测试来源"}},"未掌握复习词汇");using(var zip=ZipFile.OpenRead(path)){using(var stream=zip.GetEntry("word/document.xml").Open()){string text=XDocument.Load(stream).ToString();if(!text.Contains("中文译文")||!text.Contains("测试来源")||zip.GetEntry("word/styles.xml")==null)throw new Exception("Word export verification failed");}}}finally{if(File.Exists(path))File.Delete(path);}}
}
